/* Public RDW SODA API. No credentials, private data or backend required. */
(()=>{
const PAGE=20,base='https://opendata.rdw.nl/resource/';let searchId=0,selectionId=0,controller,timer,rows=[],query='',year='',offset=0;
const group='merk,handelsbenaming,variant,massa_rijklaar,cilinderinhoud,date_extract_y(datum_eerste_toelating_dt)';
const positive=x=>Number.isFinite(Number(x))&&Number(x)>0?Number(x):null;
function tokens(text){return text.toUpperCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim().split(/\s+/u).filter(Boolean)}
function where(text,y){const terms=tokens(text);return "voertuigsoort = 'Personenauto' AND "+terms.map(t=>`(upper(handelsbenaming) like '%${t}%' OR upper(merk) like '%${t}%')`).join(' AND ')+(y?` AND date_extract_y(datum_eerste_toelating_dt) = ${Number(y)}`:'')}
function url(dataset,params){return base+dataset+'.json?'+new URLSearchParams(params)}
async function get(dataset,params,signal){const timeout=AbortSignal.timeout(25000);const response=await fetch(url(dataset,params),{signal:signal?AbortSignal.any([signal,timeout]):timeout});if(!response.ok)throw Error('RDW HTTP '+response.status);const data=await response.json();if(!Array.isArray(data))throw Error('Unexpected RDW response');return data}
function fuelInfo(fuels){const names=fuels.map(f=>f.brandstof_omschrijving);const electric=names.includes('Elektriciteit'),petrol=names.includes('Benzine'),diesel=names.includes('Diesel');let kind=null;
if(electric&&!petrol&&!diesel&&names.every(n=>n==='Elektriciteit'))kind='electric';else if(petrol&&electric){const cls=fuels.map(f=>f.klasse_hybride_elektrisch_voertuig||'').join(' ').toUpperCase();kind=cls.includes('NOVC')?'hybrid':cls.includes('OVC')?'phev':null}else if(petrol&&names.every(n=>n==='Benzine'))kind='petrol';else if(diesel&&names.every(n=>n==='Diesel'))kind='diesel';
const combustion=fuels.find(f=>f.brandstof_omschrijving==='Benzine'||f.brandstof_omschrijving==='Diesel');const wltp=positive(combustion?.brandstof_verbruik_gecombineerd_wltp),nedc=positive(combustion?.brandstofverbruik_gecombineerd);return {kind,names:names.join(' + ')||'Топливо не указано',power:positive(combustion?.nettomaximumvermogen),consumption:kind==='petrol'||kind==='diesel'||kind==='hybrid'?wltp||nedc:null,standard:wltp?'WLTP':'NEDC'}
}
function optionText(row){const f=fuelInfo(row.fuels||[]);return [row.jaar||'Год не указан',positive(row.cilinderinhoud)?(Number(row.cilinderinhoud)/1000).toFixed(1)+' л':null,f.names,f.power?Math.round(f.power*1.35962)+' л.с.':null,row.massa_rijklaar?row.massa_rijklaar+' кг':null].filter(Boolean).join(' · ')}
function showRows(){const container=$('modelResults');container.replaceChildren();rows.forEach(row=>{const btn=document.createElement('button');btn.type='button';btn.className='model-option';btn.setAttribute('aria-pressed','false');const title=document.createElement('strong');title.textContent=row.merk+' '+row.handelsbenaming;const info=document.createElement('span');info.textContent=optionText(row);const code=document.createElement('small');code.textContent='Версия RDW: '+(row.variant||'не указана')+' · '+row.aantal+' регистраций';btn.append(title,info,code);btn.onclick=()=>choose(row,btn);container.append(btn)})}
async function search(more=false){const text=$('modelQuery').value.trim(),y=$('modelYear').value;clearTimeout(timer);const id=++searchId;controller?.abort();controller=new AbortController();selectionId++;
if(tokens(text).join('').length<2){rows=[];showRows();$('searchStatus').textContent='Введите минимум 2 буквы или цифры.';$('moreModels').hidden=true;$('searchModels').disabled=false;return}
if(!more){rows=[];offset=0;query=text;year=y;showRows()}$('moreModels').hidden=true;$('searchModels').disabled=true;$('searchStatus').textContent='Ищем варианты в реестре RDW…';
try{const batch=await get('m9d7-ebf2',{'$select':group.replace('date_extract_y(datum_eerste_toelating_dt)','date_extract_y(datum_eerste_toelating_dt) as jaar')+',min(kenteken) as kenteken,count(*) as aantal','$group':group,'$where':where(query,year),'$order':'aantal DESC,merk,handelsbenaming,jaar,variant,massa_rijklaar,cilinderinhoud','$limit':PAGE,'$offset':offset},controller.signal);
let fuelFailed=false;if(batch.length){try{const plates=batch.map(r=>r.kenteken).filter(p=>/^[A-Z0-9]+$/.test(p));const fuels=plates.length?await get('8ys7-d773',{'$where':`kenteken in (${plates.map(p=>"'"+p+"'").join(',')})`,'$limit':200},controller.signal):[];batch.forEach(r=>r.fuels=fuels.filter(f=>f.kenteken===r.kenteken))}catch(e){if(controller.signal.aborted)throw e;fuelFailed=true}}
if(id!==searchId)return;rows.push(...batch);offset+=batch.length;showRows();$('moreModels').hidden=batch.length<PAGE;$('searchStatus').textContent=rows.length?`Показано ${rows.length} вариантов · сначала наиболее распространённые.`+(batch.length===PAGE?' Ещё варианты — кнопкой ниже.':' Все найденные группы загружены.')+(fuelFailed?' Данные двигателя временно недоступны; повторим при выборе.':''):'Ничего не найдено. Попробуйте только название модели или уберите фильтр года.';
}catch(e){if(id!==searchId)return;$('searchStatus').textContent='Не удалось получить данные RDW. Проверьте интернет и нажмите «Найти» ещё раз. Можно использовать примерный сценарий ниже.';if(rows.length)$('moreModels').hidden=false}finally{if(id===searchId)$('searchModels').disabled=false}}
async function choose(row,button){const id=++selectionId;button.disabled=true;$('searchStatus').textContent='Загружаем характеристики выбранного варианта…';try{if(!row.fuels?.length)row.fuels=await get('8ys7-d773',{kenteken:row.kenteken});if(id!==selectionId)return;const f=fuelInfo(row.fuels);const weight=positive(row.massa_rijklaar);if(!weight||!f.kind){$('searchStatus').textContent='У этой записи не хватает массы или однозначного типа двигателя (возможно LPG или гибрид). Автоподстановка отменена; выберите другой вариант или введите параметры вручную.';return}
selectedRdwName=row.merk+' '+row.handelsbenaming+' · '+(row.jaar||'год неизвестен')+' · '+(row.variant||'версия не указана');$('weight').value=weight;$('fuel').value=f.kind;$('energyPrice').value=f.kind==='electric'?.35:f.kind==='diesel'?1.85:2.1;fuelUI();if(f.consumption)$('consumption').value=f.consumption;else $('consumption').value=f.kind==='electric'?18:6.5;
estimateTax();render();document.querySelectorAll('.model-option').forEach(b=>b.setAttribute('aria-pressed','false'));button.setAttribute('aria-pressed','true');$('modelProvenance').textContent='RDW · '+new Date().toLocaleDateString('ru-RU')+' · '+optionText(row)+'. Масса и двигатель из реестра.'+(f.consumption?' Расход '+f.consumption+' л/100 км ('+f.standard+'), лабораторный; фактический может быть выше.':' Расход отсутствует или неприменим к этой формуле: подставлен сценарный ориентир, уточните вручную.')+' Цена покупки, продажи, страховка и остальные расходы остаются вашими сценарными значениями. Характеристики двигателя взяты у одной регистрации внутри выбранной группы; коробка передач и коммерческая комплектация не подтверждены.';$('searchStatus').textContent='Вариант выбран. Характеристики подставлены в расчёт.';
}catch(e){if(id===selectionId)$('searchStatus').textContent='Не удалось загрузить двигатель. Расчёт не изменён. Попробуйте выбрать вариант ещё раз.'}finally{button.disabled=false}}
for(let y=new Date().getFullYear();y>=1990;y--){const o=document.createElement('option');o.value=y;o.textContent=y;$('modelYear').append(o)}
$('model').addEventListener('change',()=>{selectionId++;document.querySelectorAll('.model-option').forEach(b=>b.setAttribute('aria-pressed','false'))});
$('modelQuery').addEventListener('input',()=>{clearTimeout(timer);searchId++;selectionId++;controller?.abort();$('searchModels').disabled=false;$('moreModels').hidden=true;rows=[];showRows();$('searchStatus').textContent='Ожидаем ввод…';timer=setTimeout(()=>search(),550)});$('modelQuery').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();search()}});$('modelYear').onchange=()=>search();$('searchModels').onclick=()=>search();$('moreModels').onclick=()=>search(true);
// Keep pure transformations available to the Node regression suite.
if(typeof module!=='undefined')module.exports={where,fuelInfo,optionText};
})();
